{
  "description": "The creature is a quadrupedal, wolf-like mammal shown in right-facing profile standing on sandy ground with small stones and shells. Its body, head, hind legs and tail are covered in thick, shaggy fur in mottled gray, brown, black and cream, with a lighter belly and chest and a darker back. The head is canine with a long muzzle and yellow eyes. The two hind legs end in canine paws, while the two front legs end in large, dark, bumpy crustacean pincers that rest on the ground. A continuous row of dark, overlapping, keeled armored plates runs along the midline of the back from behind the shoulders to the base of the tail.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like head with elongated muzzle, black nose, yellow-brown eyes, gray and white fur on cheeks and forehead, mouth slightly closed",
      "where": "at the front of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two pointed, erect, triangular ears with dark gray outer fur and lighter inner fur",
      "where": "on top of the head"
    },
    {
      "part": "mane",
      "looks_like": "thick ruff of long, shaggy fur in gray, white and black",
      "where": "around the neck, throat and chest extending onto the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four legs; hind legs slender and fully fur-covered; front legs thicker and fur-covered on the upper portion with a row of small pointed spines along the lower rear edge",
      "where": "two hind legs under the rear body, two front legs under the chest and shoulders"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are canine paws with visible toes, light fur and dark claws; front feet are large, dark gray-blue crustacean chelae (pincers) with bumpy, dotted surfaces, thick joints and curved opposing claws",
      "where": "at the ends of the legs, hind paws on the ground, front pincers touching the sandy ground"
    },
    {
      "part": "tail",
      "looks_like": "long, bushy, fur-covered tail in gray, black and cream, hanging down behind the hind legs",
      "where": "at the rear of the body"
    },
    {
      "part": "plates",
      "looks_like": "row of dark gray-blue, overlapping, keeled, triangular armored scutes with a scaly texture",
      "where": "along the dorsal midline of the back from the mid-back to the base of the tail"
    },
    {
      "part": "scales",
      "looks_like": "scaly, keeled texture of the dorsal plates and bumpy, pitted, spiny texture on the front pincers and lower front legs",
      "where": "on the back midline and on the front feet and lower front legs"
    },
    {
      "part": "markings",
      "looks_like": "mottled fur pattern with darker gray-black on the back and sides, lighter cream-white on the belly, chest and inner legs, and darker streaks on the neck and flank",
      "where": "over the entire furred body"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab",
    "crocodile"
  ],
  "separate_bodies": 1,
  "heads": 1,
